args.command:
export E=/workspace/executable
echo 'Ab aB' | $E -f zzz 'a' 'X'; echo "EXIT: $?"; echo ===
# default case sensitivity
echo 'Ab aB' | $E 'a' 'X'; echo ===
echo 'Ab aB' | $E -f i 'a' 'X'; echo ===
echo 'Ab aB' | $E -f ic 'a' 'X'; echo ===
echo 'Ab aB' | $E -f ci 'a' 'X'; echo ===
# multiline default?
printf 'a \nb \n' | $E '\s+$' 'X' | od -c | head; echo ===
printf 'a \nb \n' | $E -f m '\s+$' 'X' | od -c | head; echo ===
printf 'a \nb \n' | $E -f e '\s+$' 'X' | od -c | head

export E=/workspace/executable
echo 'abc' | $E '(a)(b)(c)' '$3$2$1'; echo ===
echo 'abc' | $E '(a)(b)(c)' '$0'; echo ===
echo 'abc' | $E '(?P<x>a)(b)' '$x-$2-${x}y'; echo ===
echo 'foo' | $E 'foo' '$$bar'; echo ===
echo 'foo' | $E 'foo' '$$$1' 2>&1; echo "EXIT $?"; echo ===
echo 'foo' | $E 'foo' 'a$' 2>&1; echo "EXIT $?"; echo ===
echo 'foo' | $E 'foo' '$1x' 2>&1; echo "EXIT $?"; echo ===   # group 1 doesn't exist
echo 'foo' | $E '(f)oo' '${1}0' 2>&1; echo ===
echo 'foo' | $E '(f)oo' '$10' 2>&1; echo "EXIT $?"; echo ===  # group 10 doesn't exist
echo 'foo' | $E -F 'foo' '$1$$'; echo ===   # fixed mode: literal replacement
echo 'foo' | $E 'foo' '$x' 2>&1; echo "EXIT $?"

export E=/workspace/executable
t() { echo "--- $1"; shift; printf 'foo bar\n' | $E "$@" 2>&1; echo "EXIT $?"; }
t bad-with-i -f i '(' 'X'
t bad-with-w -f w '(' 'X'
t bad-with-m -f m '(' 'X'
printf 'a\nb\n' | $E $'(\na' 'X' 2>&1; echo "EXIT $?"; echo ===
# does -f i override (?-i) in pattern?
echo 'FOO foo' | $E -f i '(?-i:foo)' 'X'; echo ===
echo 'FOO foo' | $E -f c '(?i:foo)' 'X'; echo ===
# w flag details
echo 'foo_bar foo' | $E -f w 'foo' 'X'; echo ===
echo 'xfoo foox' | $E -f w 'foo' 'X'; echo ===
# -n with files and stdin interplay; multiple matches on zero-width
printf 'aaa\n' | $E -n 0 'a' 'X'; echo ===
printf '' | $E 'x' 'y' | od -c; echo ===
printf 'no newline' | $E 'e$' 'E' | od -c
